INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('498fada6-6516-43c7-96da-f39492eb8d66', '21feff02-016d-46e2-bb9d-c27495133b1b', '61. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek', 'Egyenlő szárú háromszög tulajdonságai és szimmetriatengelye.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "184d832e-e05c-434a-ad3b-f7088dfbd50b", "text": "Hány szimmetriatengelye van az egyenlő szárú (nem egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "efd82121-0cfd-422d-8932-5bf1f751b29e", "text": "Hány szimmetriatengelye van a szabályos (egyenlő oldalú) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "53e88462-8d17-4410-a8d4-32573a00131a", "text": "Az egyenlő szárú háromszög alapon fekvő szögei egyenlők.", "type": "true-false", "options": [{"id": "d15041a6-cf75-4e21-9bc2-74e0605e69ff", "text": "Igaz", "isCorrect": true}, {"id": "2bae6163-1dee-4e02-b24f-274ac441b782", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9cc59aa3-b673-4df0-bbb0-5c0566bb0fbe", "text": "Ha az egyenlő szárú háromszög szárai 8 cm-esek, és alapja 5 cm, mennyi a kerülete? (8+8+5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "21"}, {"id": "68e3da7c-7713-4213-a418-cd9da68e1c36", "text": "Ha az egyenlő szárú háromszög szárszöge (csúcsszöge) 40°, mekkorák az alapon fekvő szögek? ((180-40)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "78e09014-1a3c-42d2-8eb7-ff14aa2a519d", "text": "Az egyenlő szárú háromszög szimmetriatengelye az alap felezőmerőlegese és a szárszög felezője is egyben.", "type": "true-false", "options": [{"id": "15188ead-acc0-426b-ab07-0760b70320b7", "text": "Igaz", "isCorrect": true}, {"id": "b2bc9971-2cbd-48b3-bfa4-0afa25353059", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e041ef1b-5987-46ac-99b2-e751cca88591", "text": "Az egyenlő oldalú háromszög minden szöge 60°-os.", "type": "true-false", "options": [{"id": "bef16326-e139-48da-bc89-3feca62b70bb", "text": "Igaz", "isCorrect": true}, {"id": "097dffc4-d671-4085-8c44-e0e23de9b12d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e119921a-5ddb-4d9f-8dc2-53736685fb94', '21feff02-016d-46e2-bb9d-c27495133b1b', '62. óra: Tengelyesen szimmetrikus háromszögek, négyszögek, sokszögek II.', 'Tengelyesen szimmetrikus négyszögek (téglalap, négyzet, rombusz, deltoid, szimmetrikus trapéz) szimmetriatengelyei.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "15a47bac-42a7-4325-8ccb-8a9412b8e411", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "e4a93eed-d3e9-409b-baf6-4d6271aaf969", "text": "Hány szimmetriatengelye van a téglalapnak (ami nem négyzet)? (az oldalfelező merőlegesek)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "faffa3c8-8b1a-4839-afa2-75b749530a5b", "text": "Hány szimmetriatengelye van a rombusznak (ami nem négyzet)? (az átlók egyenesei)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "7dd6e499-b0e6-4edf-84e6-72e1ff9f4a24", "text": "Hány szimmetriatengelye van a deltoidnak (ha nem rombusz)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "afe7bd70-664a-4b82-8133-ba7266923a0e", "text": "A szimmetrikus (egyenlő szárú) trapéznak 1 szimmetriatengelye van.", "type": "true-false", "options": [{"id": "50ae63ff-8c02-47ca-9510-b290d9340053", "text": "Igaz", "isCorrect": true}, {"id": "938046ed-73c2-4863-9667-ac68e105a649", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7bccb093-996a-4763-90e6-f347a39f9477", "text": "Az általános paralelogrammának (ami nem rombusz és nem téglalap) NINCS tengelyes szimmetriatengelye.", "type": "true-false", "options": [{"id": "a58970e2-04e4-4ed9-9fde-e69655b8cf24", "text": "Igaz (középpontosan szimmetrikus, de tengelyesen nem)", "isCorrect": true}, {"id": "64d64513-7754-40d5-b003-a3c10faf90f6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1ebe8d08-e2ce-483d-b69f-db01710cbafb", "text": "Hány szimmetriatengelye van a szabályos ötszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f2a368fe-0f39-4513-9491-f1ef588483e0', '21feff02-016d-46e2-bb9d-c27495133b1b', '63. óra: Szerkesztési feladatok', 'Szakasz- és szögmásolás, szögfelezés, háromszögszerkesztések gyakorlása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "85fb87fa-4e4e-4337-b743-1ba9d3870410", "text": "Hogyan felezünk meg egy 80°-os szöget szerkesztéssel?", "type": "multiple-choice", "options": [{"id": "93653372-1f2a-45ae-8bfb-18cf9814f87c", "text": "Megszerkesztjük a szög szögfelező egyenesét, így két 40°-os szöget kapunk", "isCorrect": true}, {"id": "b331bcdc-5476-4c30-8241-88304723c597", "text": "Levágunk belőle 10 fokot", "isCorrect": false}, {"id": "d65626c1-209d-4c4c-8a72-bf878387a5a8", "text": "Merőlegest húzunk a szög egyik szárára", "isCorrect": false}, {"id": "0afeea09-7a89-47d0-9979-b2fb2e198d97", "text": "Szögmérővel elosztjuk", "isCorrect": false}], "timeLimit": 15}, {"id": "7274e20a-90a3-44c3-a55c-9816d8bb0691", "text": "A szögfelezéshez körzőt és egyenes vonalzót használsz.", "type": "true-false", "options": [{"id": "49ad11b5-da1a-4d4f-9101-1c80e4dc05ee", "text": "Igaz", "isCorrect": true}, {"id": "87c792d5-dc7f-48de-8e53-b4a7361d1bc7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6ffaf8b9-ec8e-4810-84fb-b3a5f04d6153", "text": "Hány fokos szögeket kapunk egy 90°-os derékszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "fe790138-b127-47de-9fe0-2c60b1a3e483", "text": "Hány fokos szögeket kapunk egy 180°-os egyenesszög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "e35c8154-1485-4bcb-85c1-5d6dc77cf6a9", "text": "Szerkeszthető-e 60°-os szög kizárólag körzővel és vonalzóval (szabályos háromszög szerkesztésével)?", "type": "true-false", "options": [{"id": "4feedb21-9d4c-4e26-80e9-141f44f4d7db", "text": "Igaz", "isCorrect": true}, {"id": "26338a7e-8144-40a7-86a5-6e4c9c4731a4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1da94133-452e-4df6-a9d1-3c739b659d1a", "text": "Szerkeszthető-e 30°-os szög a 60°-os szög felezésével?", "type": "true-false", "options": [{"id": "0d805d98-5850-4c18-94d7-e32a372a2b61", "text": "Igaz", "isCorrect": true}, {"id": "6f0456d7-4207-4f63-88fc-47a900d9fd4a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bd5fa629-f3ed-4bf4-a7e2-23bdbda769c0", "text": "Szerkeszthető-e 15°-os szög a 30°-os szög felezésével?", "type": "true-false", "options": [{"id": "6e683093-9af2-4e00-aa35-49c8a7027365", "text": "Igaz", "isCorrect": true}, {"id": "b9590d92-f9a3-4be2-aa7d-52e17f73739c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('123a8ed2-eda5-4227-97c9-aee597495753', '21feff02-016d-46e2-bb9d-c27495133b1b', '64. óra: Dinamikus szerkesztőprogram megismerése', 'Interaktív geometriai szoftverek (GeoGebra), alakzatok mozgatása, tulajdonságok megfigyelése.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "7610fc85-174a-4653-b6b0-1590dea6754e", "text": "Mire való a GeoGebra dinamikus geometriai program?", "type": "multiple-choice", "options": [{"id": "883aba7f-cf6b-4d63-95cf-4b3077f34124", "text": "Geometriai alakzatok szerkesztésére, mozgatására, mérésére és összefüggések felfedezésére", "isCorrect": true}, {"id": "2f071658-5078-4aa7-9bad-b129a12d9666", "text": "Szövegszerkesztésre", "isCorrect": false}, {"id": "7ea5149b-c21e-4b6f-aa72-a2d3ed99d7b6", "text": "Videóvágásra", "isCorrect": false}, {"id": "abdc02b3-2402-4944-87f9-f04d8daf44ad", "text": "Kódolásra C++ nyelven", "isCorrect": false}], "timeLimit": 15}, {"id": "71522383-7719-423d-aa39-fc4ee00b156c", "text": "Dinamikus szerkesztőprogramban az csúcsok mozgatásakor az alakzat tulajdonságai és összefüggései megőrződnek.", "type": "true-false", "options": [{"id": "495ca002-2d83-4468-9293-d199167a6650", "text": "Igaz", "isCorrect": true}, {"id": "7c6a4851-4dbb-4700-84ad-18106705e71a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "27a04669-e48f-4966-bddc-e9d45e911150", "text": "A dinamikus programokban a háromszög belső szögeinek összege mozgattatás közben is mindig 180° marad.", "type": "true-false", "options": [{"id": "114f3e99-f999-4d57-9eee-28f0aecb04a8", "text": "Igaz", "isCorrect": true}, {"id": "972ffc9b-26ef-43f9-8faf-62ee3ffe48b3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "822e5a64-e25f-46dd-b1ed-d8701ad692e9", "text": "A szerkesztőprogram segítségével ellenőrizhető a kézi szerkesztések pontossága.", "type": "true-false", "options": [{"id": "abf1db57-71b0-4b6b-9592-1e2cb3104af9", "text": "Igaz", "isCorrect": true}, {"id": "ed7d9405-2a06-4a1d-85d1-6e5340365bb9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5df4037b-d1fa-4048-a2ee-e200ed6bd974", "text": "Melyik funkció segít a pontok tengelyes tükörképének azonnali előállításában a szoftverben?", "type": "multiple-choice", "options": [{"id": "f5b5a192-a07a-4d38-b42a-963782dbab2c", "text": "Tengelyes tükrözés eszköz", "isCorrect": true}, {"id": "df946f68-2843-4e15-87f5-63d67182d6e0", "text": "Színezés", "isCorrect": false}, {"id": "5119b8d3-b2c2-4dc5-85f7-9f95602cfc93", "text": "Törlés", "isCorrect": false}, {"id": "26f6b216-0fda-49ae-b1cb-eaf67540d4f1", "text": "Nagyítás", "isCorrect": false}], "timeLimit": 15}, {"id": "d58a7565-aeee-41c0-92be-e27ad40130fe", "text": "A számítógépes geometriai modellezés segíti a mélyebb megértést.", "type": "true-false", "options": [{"id": "a11e49b9-1401-4508-b84f-5d2efaa6c7b6", "text": "Igaz", "isCorrect": true}, {"id": "30e60a5c-295c-4228-bdda-d9fba1be840f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b611d840-2081-44c3-bbcd-679c03a3ae2f", "text": "Hány fok a teljes szög a geometriában?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d2749930-0885-4b10-a02f-f9a369052b6a', '21feff02-016d-46e2-bb9d-c27495133b1b', '65. óra: Összefoglalás', 'A Geometria és tengelyes tükrözés fejezet fogalmainak, szerkesztéseinek összefoglalása.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "d0d11015-456f-479e-8aac-c74443acd561", "text": "Hány szimmetriatengelye van a téglalapnak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "f8372905-3399-424f-a925-099a811bc355", "text": "Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "fb47cb36-d09c-4e44-ada3-ba1e6cc7cd76", "text": "A tengelyes tükrözés megváltoztatja a síkidom körüljárási irányát.", "type": "true-false", "options": [{"id": "f91f5a4a-8547-4a22-9580-89205949fa0c", "text": "Igaz", "isCorrect": true}, {"id": "6fc8fd12-f405-444a-a7cd-f03598c1671c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f28dcc3-af97-44ea-849e-2a30a8d1521f", "text": "Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "d3a078b9-f2f3-4b24-a901-befe49189171", "text": "A szakaszfelező merőleges minden pontja egyenlő távolságra van a szakasz két végpontjától.", "type": "true-false", "options": [{"id": "82b0470c-237a-43da-baf4-5edb1b7653d4", "text": "Igaz", "isCorrect": true}, {"id": "7590573d-7951-4c57-b517-0d9262aaa7e0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bfaae1c8-dbd5-4edd-a4ec-010aef84db94", "text": "Ha a kör átmérője 12 cm, mekkora a sugara? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "c1625b94-3b83-4afd-a6ef-56ca8913bfb3", "text": "A szögfelező egyenes felezi a szöget és egyenlő távolságra van a szög száraitól.", "type": "true-false", "options": [{"id": "cc52611e-3820-4808-a690-bf0214566a54", "text": "Igaz", "isCorrect": true}, {"id": "53f96195-51e3-454c-8c67-77f7f59f4bd2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('7b421b22-9429-4951-af36-feded2cc9214', '21feff02-016d-46e2-bb9d-c27495133b1b', '66. óra: Témazáró dolgozat', 'Témazáró számonkérés a Geometria és tengelyes tükrözés fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "7c2c73c5-128a-41b9-88fe-9aa909e8d596", "text": "1. Mennyi a háromszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "def14bc1-8225-4995-b70e-a47427530cc4", "text": "2. Mennyi a négyszög belső szögeinek összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "3d5fb753-9d6d-4ed4-b4fa-285665b4ece7", "text": "3. Hány szimmetriatengelye van a négyzetnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "69f9cfed-6ba0-43e9-8270-b4e51d12af08", "text": "4. Hány szimmetriatengelye van az egyenlő szárú (nem szabályos) háromszögnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "0604f866-f6dc-4cec-9f61-e8f827472801", "text": "5. Ha a kör sugara 4,5 cm, mekkora az átmérője? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "3dcf5d6f-acde-4206-b3c7-050616cf0463", "text": "6. A tengelyes tükrözés távolságtartó transzformáció.", "type": "true-false", "options": [{"id": "3d900403-0a39-4bcb-b80b-a690754ee79c", "text": "Igaz", "isCorrect": true}, {"id": "11b33f4d-7f73-4b10-a12c-e4dc4b0be3bb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b6220f81-a140-4a2c-a926-f59452e714bb", "text": "7. Szerkeszthető-e háromszög 3 cm, 5 cm, 9 cm oldalakkal?", "type": "true-false", "options": [{"id": "b14eae39-b1f9-42d1-ab34-d240bf71fa90", "text": "Igaz", "isCorrect": false}, {"id": "70560b02-938a-468d-a250-3984b6e06ce9", "text": "Hamis (3+5 < 9)", "isCorrect": true}], "timeLimit": 15}, {"id": "6fd755bb-f508-44c5-8f95-db0197dcf220", "text": "8. Hány fokos szögeket kapunk egy 120°-os szög felezésekor?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "33081b46-f357-47d3-9b74-b7dcf1c34f1f", "text": "9. A rombusz minden oldala egyenlő hosszú.", "type": "true-false", "options": [{"id": "cc57137e-9581-4bd8-bb96-4fe23cbb68a8", "text": "Igaz", "isCorrect": true}, {"id": "cb39213f-dbb9-43b9-9fa8-680bd501f640", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "25926398-68ff-45c4-8cbb-1a618bae7dbf", "text": "10. Hol található a tükörtengelyen lévő pont tükörképe?", "type": "multiple-choice", "options": [{"id": "440d48a9-1ab4-441b-94af-ff9bc834da15", "text": "Önmagában", "isCorrect": true}, {"id": "6b5b6b8c-f5ab-4b3c-bdbe-7028b35bc91c", "text": "Az origóban", "isCorrect": false}, {"id": "62e71b46-ac60-4af4-93a4-7e5d19c478c3", "text": "A tengely végétől 5 cm-re", "isCorrect": false}, {"id": "e18f475e-2d2e-4073-b2d8-5829c6a33da8", "text": "A sík szélén", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e9e2e7d8-36fe-4208-8e5e-6b8f6ee0435f', '21feff02-016d-46e2-bb9d-c27495133b1b', '67. óra: Témazáró dolgozat értékelése', 'A geometriai témazáró megbeszélése, szerkesztések értékelése és hibajavítás.', 'Matematika', '6. osztály', 'Geometria, tengelyes tükrözés', '[{"id": "07b8b02c-394c-4747-9ca5-03ef2cb3d0a4", "text": "Mi volt a leggyakoribb hiba a szerkesztési feladatok során?", "type": "multiple-choice", "options": [{"id": "836e49f2-fa10-46d1-87fa-e12fe2515117", "text": "A körző pontatlan használata és a háromszög-egyenlőtlenség figyelmen kívül hagyása", "isCorrect": true}, {"id": "b62f99a8-5e36-4b9d-8b6a-447c5cfb443e", "text": "A ceruza színe", "isCorrect": false}, {"id": "fe5e2257-9372-441f-ad02-33c4910df561", "text": "A füzet vonalazása", "isCorrect": false}, {"id": "b962937e-a126-4f3a-8449-6ebcbfda7209", "text": "A számok leírása", "isCorrect": false}], "timeLimit": 15}, {"id": "5165cffe-f2b8-4c71-a524-7c64616e3488", "text": "A szakaszfelező merőleges merőleges a szakaszra és átmegy a felezőpontján.", "type": "true-false", "options": [{"id": "03a97a07-99b0-4c16-9fba-117a94af77f8", "text": "Igaz", "isCorrect": true}, {"id": "19e94303-ca51-4685-a19c-6ffe4fa5216f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8df6a9da-e9f7-4417-b846-df07b4020cdc", "text": "Mennyi a kör átmérője, ha a sugara 10 cm?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "b17dca64-d0c2-4954-b870-441e240a9853", "text": "A tengelyes tükrözés során a síkidom területe nem változik.", "type": "true-false", "options": [{"id": "205c0c29-cdbf-4c2a-ab5b-ca9ffe4c98e4", "text": "Igaz", "isCorrect": true}, {"id": "8ec42ab7-4776-4ac5-a91d-846915ec516d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1867026e-5db2-498f-9c4e-4f0f3276f134", "text": "Hány szimmetriatengelye van a körnek?", "type": "multiple-choice", "options": [{"id": "57367c68-067c-4311-91af-4201ebdedfc1", "text": "Végtelen sok", "isCorrect": true}, {"id": "0732b7bb-24a8-4658-8fa6-4625b9a088bc", "text": "1", "isCorrect": false}, {"id": "344ba7ce-c168-47e9-989b-5271ae7b38cd", "text": "2", "isCorrect": false}, {"id": "82b6fd17-adb6-4399-b146-6961399be5a5", "text": "4", "isCorrect": false}], "timeLimit": 15}, {"id": "131e3926-e6d8-47c2-839f-52854f55ac8b", "text": "A pontos vázlatkészítés megkönnyíti a bonyolultabb szerkesztések elvégzését.", "type": "true-false", "options": [{"id": "7bd03d69-7f13-4dd7-ae3d-ecd0a8b7a6aa", "text": "Igaz", "isCorrect": true}, {"id": "c281051c-2806-437b-a8d9-026c4f950d31", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ff5b7fbf-ca70-41f2-98e4-a30165e4b9ef", "text": "Mennyi a háromszög harmadik szöge, ha az első kettő 50° és 70°?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f92d4d9e-071c-4ed3-bc3d-d92bd1760814', '21feff02-016d-46e2-bb9d-c27495133b1b', '68. óra: Az arány fogalma', 'Az arány fogalma, felírása kettősponttal és törttel, értelmezése hétköznapi példákban.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "2f767984-63f5-4136-bee5-7ee858e650e4", "text": "Mit fejez ki két mennyiség aránya?", "type": "multiple-choice", "options": [{"id": "0c437ad2-b800-4aa8-b25b-4c80ffcd7a7a", "text": "Megmutatja, hányszorosa az egyik mennyiség a másiknak (hányadosukat)", "isCorrect": true}, {"id": "3dab04e4-41c3-4867-9e4e-563c4fb04b9b", "text": "Megmutatja a két mennyiség összegét", "isCorrect": false}, {"id": "89cd0326-0834-469f-8d63-bbb97a0b189c", "text": "Megmutatja a két mennyiség szorzatát", "isCorrect": false}, {"id": "825d0b8c-a4cf-4345-8b75-e555d93ac050", "text": "Nem fejez ki semmit", "isCorrect": false}], "timeLimit": 15}, {"id": "12a63afb-1cd3-4552-be9d-29dced3f26d5", "text": "Hogyan jelöljük az arányt matematikailag?", "type": "multiple-choice", "options": [{"id": "f6f8365e-6220-4d56-915d-705e2c3e3558", "text": "Kettősponttal (pl. 2 : 3) vagy törttel (2/3)", "isCorrect": true}, {"id": "c0ae1d13-d9f8-4dcf-b324-5cf79cca5a0d", "text": "Plusz jellel", "isCorrect": false}, {"id": "821e9fea-3d2c-4e8d-b472-c41d208188ff", "text": "Csillaggal", "isCorrect": false}, {"id": "0cfed4c1-6d3b-4d68-b356-d43c94a99c47", "text": "Egyenlőségjellel", "isCorrect": false}], "timeLimit": 15}, {"id": "20852cc4-731e-457b-bb55-e4f2402dd9b5", "text": "Ha egy osztályban 10 fiú és 15 lány van, mi a fiúk és lányok számának aránya legegyszerűbb alakban?", "type": "multiple-choice", "options": [{"id": "29428616-0425-444f-96a8-e6df98f80c87", "text": "2 : 3 (10/15 egyszerűsítve 5-tel)", "isCorrect": true}, {"id": "8a48471b-fedc-4e19-a90f-93f0fc7149c7", "text": "1 : 2", "isCorrect": false}, {"id": "717f5194-eb52-4c75-adaa-38df6c6104de", "text": "3 : 2", "isCorrect": false}, {"id": "05aca4f6-b909-4c4c-a4c6-23b7c99e5a1a", "text": "10 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "78f981cb-f959-4ee0-9107-8de28b423334", "text": "Az arány a törtekhez hasonlóan egyszerűsíthető és bővíthető.", "type": "true-false", "options": [{"id": "49fe421e-35b1-4a51-86af-b4ba5f9b90ca", "text": "Igaz", "isCorrect": true}, {"id": "1ee26158-5f0f-4a9f-8e22-f8dc349636a3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "86f14742-7e8d-4724-9231-bea913f4bbfa", "text": "Mennyi a 4 : 8 arány egyszerűsített alakja?", "type": "multiple-choice", "options": [{"id": "40be6f4e-3764-48bb-8fbb-ed518dc217f1", "text": "1 : 2", "isCorrect": true}, {"id": "8976f35f-7719-4da0-aa19-e137b866fac6", "text": "2 : 4", "isCorrect": false}, {"id": "e1133941-12b4-47cc-8ea9-3efde880886e", "text": "1 : 4", "isCorrect": false}, {"id": "609f8aa5-13ed-44a3-a465-f2ae051021f6", "text": "4 : 1", "isCorrect": false}], "timeLimit": 15}, {"id": "f83ace10-a478-450a-b1d3-75563137ff86", "text": "Ha az arány 3 : 1, az első mennyiség 3-szor akkora, mint a második.", "type": "true-false", "options": [{"id": "ee51c513-82ea-4317-95c7-e8b92459d8ad", "text": "Igaz", "isCorrect": true}, {"id": "b1d3944a-9b42-41b7-8c64-48f5ab2a993d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4883d962-2a32-49f7-9bda-f3825279e697", "text": "Melyik arány egyenlő az 1 : 2 aránnyal?", "type": "multiple-choice", "options": [{"id": "e26bbc9c-527e-4b1c-8270-f44de696bdd2", "text": "5 : 10", "isCorrect": true}, {"id": "406cf97b-98c4-4b2e-a6a8-ff8cd162d4df", "text": "2 : 1", "isCorrect": false}, {"id": "0d81a132-81e3-4130-ac9f-856ce8778ad9", "text": "3 : 5", "isCorrect": false}, {"id": "9726c9b1-b043-4fbb-b963-e5816503ceb3", "text": "4 : 6", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4e81d110-1a3e-4de7-a553-e1a9ce1a2ca5', '21feff02-016d-46e2-bb9d-c27495133b1b', '69. óra: Arányos osztás', 'Adott mennyiség felosztása megadott arányban (pl. 2 : 3 arányban).', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "fda6ea0e-7d0b-474a-9c7b-31a1f8e022c5", "text": "Ha 500 Ft-ot elosztunk 2 : 3 arányban, hány egyenlő részre osztjuk először a teljes összeget?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "82844c15-5426-4ce0-bfe7-7c0e143c8eab", "text": "Hány Ft a kisebbik rész 500 Ft 2 : 3 arányú felosztásakor? (1 rész = 100 Ft, 2 rész = 200 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "200"}, {"id": "5a857791-2836-4684-9af2-f8bbd5954474", "text": "Hány Ft a nagyobbik rész 500 Ft 2 : 3 arányú felosztásakor? (3 rész = 300 Ft)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "300"}, {"id": "e56c5205-1854-4573-9cca-86aa0c49c621", "text": "Az arányos osztásnál az arányszámok összege megadja az összes egység (rész) számát.", "type": "true-false", "options": [{"id": "5549755a-05d5-4bd6-b1e2-d98f696bee8d", "text": "Igaz", "isCorrect": true}, {"id": "ce051b60-15a7-48c8-849e-377f2629e18a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a182da47-fb03-49a4-a4e8-68ef51b3779c", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a nagyobbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "45e7e070-61e4-41d0-b17f-26f98e111fe2", "text": "Ossz el 30 szem cukorkát 1 : 2 arányban! Hány cukorka a kisebbik adag?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "524ec978-b674-4399-b567-2d9805be7886", "text": "Az arányos osztási feladatok ellenőrizhetők a kapott részek összegzésével.", "type": "true-false", "options": [{"id": "79a8e3bc-c7d4-4958-ae1c-d56b13d8781b", "text": "Igaz", "isCorrect": true}, {"id": "0569a8b4-9dc8-4ab8-b164-d1559463266e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ffba4553-b4a3-4c07-bda7-0fbaff5a0e04', '21feff02-016d-46e2-bb9d-c27495133b1b', '70. óra: Feladatok megoldása', 'Hétköznapi recept, ötvözet, keverék és arányos osztási feladatok.', 'Matematika', '6. osztály', 'Arány, százalék, szöveges feladatok', '[{"id": "597672c9-ffb7-458d-b2c0-7642be67ef41", "text": "Egy habarcs készítéséhez homok és mész kell 4 : 1 arányban. Hány kg homok kell 50 kg habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "8f35c010-52e2-41ab-94fa-1d9b367519f9", "text": "Egy szörp elkészítéséhez szörp és víz kell 1 : 4 arányban. Hány dl szörp kell 10 dl (1 liter) italhoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "799dada3-5989-4787-a1d0-152327862194", "text": "Ha két testvér 3 : 5 arányban osztozik 800 Ft-on, a nagyobbik rész 500 Ft.", "type": "true-false", "options": [{"id": "f6f2e4a2-beb7-4267-91a1-720d514ed396", "text": "Igaz (800 / 8 = 100, 5 * 100 = 500)", "isCorrect": true}, {"id": "4339252e-5724-4ba7-a567-94f8aa422cce", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "00ed2dc4-d32d-41b3-87dd-882fb0a9b401", "text": "Egy téglalap két szomszédos oldalának aránya 2 : 3. Ha a rövidebb oldal 6 cm, hány cm a hosszabb oldal?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "c3ed0ab4-e410-44a8-87f2-1e590a07fbb6", "text": "Melyik állítás igaz az arányos osztásra?", "type": "multiple-choice", "options": [{"id": "95e03de9-9488-45a4-9c95-1b17aefd0a40", "text": "A kapott részek aránya megegyezik a megadott aránnyal", "isCorrect": true}, {"id": "146f0a57-b24a-402c-ab7f-b47ba700055d", "text": "Minden rész egyenlő nagyságú", "isCorrect": false}, {"id": "33dd93ba-79fa-4277-9a59-7fb43313374e", "text": "A részek összege kisebb az eredeti mennyiségnél", "isCorrect": false}, {"id": "76679852-1abd-48d0-b981-8855673ac5c6", "text": "Nem lehet kiszámolni", "isCorrect": false}], "timeLimit": 15}, {"id": "21996d30-ef74-4296-b9c7-6bc41bc68535", "text": "Hány g mész kell 50 kg (4:1 arányú) habarcshoz?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "86a09b6e-d9b4-455a-9b4b-abd0ebc38e85", "text": "A receptekben megadott hozzávalók aránya lehetővé teszi tetszőleges adag elkészítését.", "type": "true-false", "options": [{"id": "f625a071-ffd4-43c3-887a-0bfc0bf20f01", "text": "Igaz", "isCorrect": true}, {"id": "61dccb3f-0b9e-4cfe-a9f5-3a1f44c4886a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;